"use strict";(self.webpackChunkwhaleal_platform=self.webpackChunkwhaleal_platform||[]).push([[875],{3462:function(e,t,a){a.d(t,{G:function(){return n}});const n=[{slug:"byol-connections",name:"Bring-your-own provider connections",h1:"Connect the provider accounts you already pay for",eyebrow:"Feature · Connections",metaTitle:"BYOL connections — your own messaging accounts",metaDescription:"Connect your own CPaaS or BSP accounts per channel, keep your contract and your pricing, and let the platform work above them.",lede:"You keep the provider relationship you already have, connect it once, and the platform treats that account as a send path it can route through, pace against and read receipts from.",sections:[{h:"Connections are per channel",p:["A connection holds the credentials for one provider account on one channel. An SMS connection, an email connection and a WhatsApp connection each carry their own credentials, their own limits and their own receipts — they are not one generic “channel” object with a type field."],bullets:["SMS — the providers the console can connect today, each with the credential fields your provider actually requires","Email — your own sending account with that provider","WhatsApp — your own business account and its credentials"]},{h:"Your contract, your pricing, your numbers",p:["Because the account stays yours, so do the volume commitments, the rates and the sender identities attached to it. Nothing is repriced on the way through, and the connection never gives the platform control of your provider contract."],bullets:["No markup on message credits — you pay your provider directly","Your existing sender numbers and registrations stay attached to your account","Disconnecting a provider leaves your account untouched"]},{h:"What stays with your provider",p:["A connection gives the platform a send path, not control of your account. Registering a sender ID, raising a provider quota and approving a WhatsApp template are provider-side actions that stay with your team and the provider you already work with — which is also why they cannot be skipped by connecting here."]}],faq:[{q:"Do I need to move my numbers or traffic to you?",a:"No. The accounts stay with your provider; the platform is given credentials so it can send through them and read status back."},{q:"Can I connect more than one account on the same channel?",a:"Yes, and that is the point — multiple connected accounts on one channel are what makes routing and failover possible."},{q:"What credentials does a connection need?",a:"Each provider lists the fields it requires, and the console only asks for those. Credential requirements per provider are documented in the integrations section."}],guides:["byol","sender-selection"]},{slug:"routing-and-failover",name:"Routing and automatic failover",h1:"Routing and automatic failover",eyebrow:"Feature · SMS channel",metaTitle:"Routing and automatic failover for SMS",metaDescription:"Send across more than one connected SMS account, with automatic failover when one stops accepting traffic.",lede:"One provider account is a single point of failure that you cannot see failing until customers tell you. Routing across several accounts turns that into a failover you configure once.",sections:[{h:"Built end to end on the SMS channel",p:["Automatic failover between connected accounts ships on the SMS channel — the channel where provider-side failures are the ones that hurt: a number throttled, an account suspended, a route that quietly stops accepting traffic. That path is built end to end, which is why this is where the feature lives."]},{h:"What routing changes",p:["Failover changes which provider carries a message. The destination carrier still decides whether it lands, and a route that is wrong on every account still has to be fixed at the source — because there would be nowhere left to route to."],bullets:["A single send can be carried by any of your connected SMS accounts","An account that stops accepting traffic is taken out of the route","A problem that affects every account surfaces instead of hiding behind a retry"]},{h:"How it works together with pacing",p:["Failover and pacing solve different problems: pacing keeps you under the limit a provider applies per number, failover keeps traffic moving when an account stops working. Configure both, and neither failure mode is left open."]}],faq:[{q:"Is failover available for email or WhatsApp?",a:"Failover across connected accounts ships on the SMS channel today. Email and WhatsApp carry their own provider-side limits and are handled separately."},{q:"Does failover guarantee delivery?",a:"No. It changes the provider carrying the message. Delivery still depends on the destination network accepting it."},{q:"What decides the order accounts are tried in?",a:"Routing works across the accounts you have connected for that channel. The mechanics and their limits are described in the routing guide rather than restated here."}],guides:["routing-failover","two-rate-limits"]},{slug:"delivery-receipts",name:"Normalized delivery receipts",h1:"Delivery receipts, normalized across providers",eyebrow:"Feature · All channels",metaTitle:"Delivery receipts — one status, every provider",metaDescription:"Providers report delivery in their own vocabulary. The platform normalizes those receipts into one status your systems can read.",lede:"Two providers describe the same outcome with two different words, and neither word means what the reader assumes. Normalizing receipts into one status is what makes a receipt usable in code rather than as a screenshot.",sections:[{h:"One status across your providers",p:["Receipt collection and normalization run on every channel whose provider reports delivery back: on SMS that is every provider we connect, on email it is Resend, and on WhatsApp it is Meta. Whichever account carried the message, your system reads one normalized status — delivered, failed, or still awaiting a receipt — instead of a provider-specific word it has to translate itself. That is what makes a receipt usable in code."]},{h:"What a receipt actually tells you",p:["A delivery receipt says the destination network accepted the message. It does not say a human read it, and it does not say the handset displayed it. Treating a receipt as proof of reading is the most common misreading of the data."],bullets:["Accepted by the destination network — the normal reading of a delivery receipt","Rejected with a reason — carries the provider’s error, normalized where possible","No receipt at all — the message may still have arrived; absence is not proof of failure"]},{h:"Where receipts go",p:["Receipts are recorded against the message log and can be pushed to an endpoint you configure, so a system that needs to react does not have to poll. Callback delivery has its own reliability characteristics, which the guides cover explicitly rather than glossing over."]}],faq:[{q:"Do receipts work for email and WhatsApp?",a:"Where the provider reports delivery back, yes. Every SMS provider we connect does; on email that is Resend, and on WhatsApp that is Meta. The other providers in each channel are connected for sending today, and their delivery events are not wired back yet — the provider pages on /integrations/ say which is which."},{q:"Can I tell whether a message was read?",a:"No. A receipt reflects acceptance by the destination network, not attention from the recipient."},{q:"What if a receipt never arrives?",a:"Absence of a receipt is not the same as failure. The messages-not-arriving help article walks through how to tell the two apart."}],guides:["delivery-receipts","callback-reliability"]},{slug:"opt-out-suppression",name:"Opt-out and suppression",h1:"Opt-out and suppression, applied where they belong",eyebrow:"Feature · All channels",metaTitle:"Opt-out suppression for promotional SMS",metaDescription:"Opt-out keywords are honored and suppressed for promotional SMS, while transactional messages continue.",lede:"Suppression is the part of messaging that is easy to get almost right and expensive to get wrong: honour it too broadly and confirmations stop arriving; honour it too narrowly and you are ignoring a customer who asked you to stop. Getting it right is the whole feature.",sections:[{h:"Promotional traffic only",p:["Opt-out suppression is applied to promotional traffic. Transactional messages — a one-time code, a delivery notice — are not suppressed by the same rule, because a customer who opts out of marketing has not asked to lose their login code."]},{h:"Matching is exact on purpose",p:["Opt-out keywords are matched exactly rather than fuzzily. A loose match catches “STOP” inside unrelated text and silently suppresses a customer who never asked for it, which is a worse failure than the one it prevents."],bullets:["Opt-out keywords honoured per the rules you configure","Promotional sends filtered against the suppression record","Transactional sends unaffected"]},{h:"Where the suppression record comes from",p:["The check that filters a promotional send runs before every marketing send, on any channel you have connected — and the list is per channel rather than shared, so an SMS opt-out does not silence email. The automatic path that writes a record is the keyword one: SMS, where STOP, HELP and START are part of how the channel works. The list is visible and reversible from the console, per channel. Consent — who agreed to be messaged, when, and how that is recorded — stays on your side; the platform applies the suppression it is given, exactly as configured."]}],faq:[{q:"Will opting out stop a customer’s verification codes?",a:"No. Suppression is applied to promotional traffic, not to transactional sends."},{q:"Can someone be re-subscribed?",a:"Yes, and the resubscribe path is deliberate rather than implicit — it is covered in the guides and should be used whenever a customer asks to be contacted again."},{q:"Is suppression available on email and WhatsApp?",a:"The check that filters promotional sends runs on every channel you connect, and the list is kept per channel — an SMS opt-out does not silence email. What is SMS-only is the automatic keyword path: STOP, HELP and START arriving as a reply is how a record gets written without anyone touching the console."}],guides:["opt-out","message-type-and-consent"]},{slug:"message-pacing",name:"Pacing at the provider’s real limit",h1:"Pacing at the limit your provider actually applies",eyebrow:"Feature · SMS channel",metaTitle:"Message pacing at your provider’s real limit",metaDescription:"A single application quota hides the constraint that blocks you. Pacing is applied per sender number, at the limit your provider actually enforces.",lede:"The limit that stops your traffic is not your application’s quota — it is the rate your provider applies per sender number. One number, one limit, and a batch that ignores it fails partway through.",sections:[{h:"Why one quota is the wrong number",p:["A platform-wide “messages per second” setting tells you nothing about whether a specific number can absorb a batch. Because the provider’s limit is attached to the number, pacing is configured and applied at that same granularity — add a number, and you genuinely add throughput."],bullets:["Rate limits shown per connected sender number","Pacing applied per number rather than across the account as a whole","Additional numbers raise the ceiling instead of splitting the same allowance"]},{h:"Batches drain predictably instead of failing",p:["When a batch exceeds what a number can absorb, the platform paces it out rather than sending into the wall. That turns a partial failure into a longer send, which is a trade you can plan for — and the pace is visible in the logs while it runs."]},{h:"Pacing that matches the real per-number limit",p:["Pacing at the per-number limit ships on the SMS channel, where the provider applies its rate to the sender number itself. Email and WhatsApp carry their own limits, handled by those channels rather than through this pipeline."]}],faq:[{q:"Can I send faster by raising my plan?",a:"Throughput here is set by your provider’s limit per number, not by a platform plan ceiling. Adding sender numbers or accounts is what raises it."},{q:"What happens to a message that cannot be sent within the window?",a:"Pacing spreads the batch; it does not silently drop messages. How long a large batch takes depends on the limit attached to the numbers carrying it."},{q:"Do you pace email the same way?",a:"Per-number pacing ships on the SMS channel. Email and WhatsApp limits are separate and are managed by those channels."}],guides:["pacing","two-rate-limits"]},{slug:"sender-identity",name:"Sender identity you own",h1:"Sender identity stays attached to your accounts",eyebrow:"Feature · Identity",metaTitle:"Sender identity — numbers and IDs you own",metaDescription:"The number or ID a message comes from belongs to your account, not to the platform. Registration and verification stay in your name.",lede:"The sender is the first thing a recipient sees and the thing that decides whether a message is trusted. Because that identity sits on your own account, it stays with you however you choose to send.",sections:[{h:"What a sender identity can be",bullets:["Long codes — a standard number, the easiest to obtain and the most heavily rate-limited","Short codes — higher throughput, carrier approval required","Alphanumeric sender IDs — a name instead of a number, supported in some countries only","Toll-free numbers — where the country supports them"],p:["Which of these you can use depends on the destination country and on your provider. The platform sends from the identity you already hold on the connected account, so it travels with you."]},{h:"Registration is yours, and it is worth doing early",p:["Many destinations require the sender to be registered and verified before traffic is accepted — 10DLC and short-code programs being the best-known examples. Those registrations are filed by you, with your provider or the relevant authority, which is also why they sit in your name and stay with you."],bullets:["Registration and verification are filed by you, with your provider or the relevant authority","Nothing in the middle can raise a provider quota or lift a carrier filter","An unregistered sender is rejected by the destination network, so registering early is part of going live"]},{h:"Choosing between numbers",p:["When a country supports several identity types, throughput and deliverability differ. The practical guidance — when a short code is worth the approval process, and when a second long code is enough — is in the sender selection guide."]}],faq:[{q:"Do you provide numbers?",a:"No. Sender identities belong to the provider account you connect, and the platform sends from the identity already on that account."},{q:"Will you file a 10DLC registration for us?",a:"No — registration and verification are filed by you, in your own name with your provider or the relevant authority."},{q:"Why does one number send slower than another?",a:"Different identity types carry different throughput limits. Long codes are the most limited, which is usually why a second number is added rather than a higher plan bought."}],guides:["sender-selection","sms-segments"]},{slug:"send-api",name:"Send API",h1:"A send API your own service can call",eyebrow:"Feature · API",metaTitle:"Send API — send messages from your own application",metaDescription:"An HTTP API for sending messages from your own service, with per-tenant keys, message status and receipts read back. Channel-scoped endpoints.",lede:"Product messaging is emitted by code, not typed by a person. The API exists so the service that knows an event happened is the service that sends the message about it.",sections:[{h:"Endpoints are channel-scoped",p:["Send endpoints are organized by channel, and the SMS channel is the one with a published reference today. Each channel gets the request shape its transport actually needs rather than one lowest-common-denominator call that fits none of them well."]},{h:"What the API gives you",bullets:["Authenticated sends using a per-tenant API key rather than a shared account credential","Message status readable after the send — the acceptance outcome, and the delivery status wherever the provider reports it back","Logs queryable so a support question can be answered from the record"]},{h:"Two things to design for",p:["There is no idempotency key on the send call, so a retried request sends a second message — duplicate prevention belongs in your caller. And a send is not a transaction: the API returns acceptance, while the outcome arrives later as a receipt. Both are worth designing for before you go live rather than after."]}],faq:[{q:"Is there an SDK?",a:"The API is HTTP; what a caller needs is the authentication header and the request shape, both documented in the API reference."},{q:"Can one API key send on every channel?",a:"Keys are per tenant, and the send endpoints themselves are channel-scoped — the API reference lists each one with its request shape."},{q:"Does the API retry a failed send?",a:"No. A failed send records its error and the caller decides whether to retry — which is also why idempotency has to live on your side."}],guides:["no-idempotency","sms-segments"]},{slug:"receipt-webhooks",name:"Receipt webhooks",h1:"Push receipts to your own endpoint",eyebrow:"Feature · Events",metaTitle:"Receipt webhooks to your own endpoint",metaDescription:"Configure an endpoint per tenant and let the platform push delivery receipt events to it, instead of polling for status.",lede:"Polling for status works until the volume makes it wasteful. A callback lets the system that cares about an event be told about it, which also means the record lands in your own database at the same time.",sections:[{h:"How it is configured",p:["A callback endpoint is set per tenant, and the platform pushes receipt events to it as they are normalized. The destination is yours, so the event can be recorded, acted on, or fanned out internally without asking the platform again."],bullets:["Endpoint configured per tenant","Receipt events pushed rather than polled","The event record also lives in your own system"]},{h:"How callback delivery behaves",p:["A webhook is not a database write. Endpoints go down, deployments return errors, and a push can be lost — so design the handler to be idempotent and reconcile against the message log, which is the authoritative record."],bullets:["Make the handler idempotent — the same event may arrive more than once","Reconcile against the logs rather than assuming every push arrived","Treat the callback as a fast path, not as your system of record"]},{h:"What the events carry",p:["The events pushed are the ones the platform produces — delivery receipts that have been normalized into one status vocabulary, so your endpoint receives a stable value rather than a provider-specific word it has to interpret."]}],faq:[{q:"How many times will a callback be retried?",a:"Treat the callback as best-effort: make the handler idempotent and reconcile against the message log, which is your record of truth. The callback guide sets out the model."},{q:"Can I have more than one endpoint?",a:"The callback destination is configured per tenant. Fan-out to several internal consumers is something your own endpoint can do once it receives the event."},{q:"Do webhooks cover email and WhatsApp?",a:"Where the provider reports delivery back, yes — every SMS provider we connect, Resend on email and Meta on WhatsApp. Those events are normalized into the same statuses and pushed to the same endpoint, so one handler covers them. Providers whose delivery events are not wired back yet are named on their /integrations/ pages."}],guides:["callback-reliability","delivery-receipts"]},{slug:"message-logs-and-usage",name:"Message logs and usage",h1:"A record of every send, and what it cost you",eyebrow:"Feature · Observability",metaTitle:"Message logs and usage — a record of every send",metaDescription:"Filterable message logs and usage you can read back, so a support question is answered from the record rather than from memory.",lede:"The first question after any messaging incident is “what did we actually send?”. That answer should come from a log with a filter on it, not from a reconstruction.",sections:[{h:"What the logs hold",bullets:["Each send with its channel, connection and status","Failure reasons where the provider returned one","Delivery receipt status once it arrives","Filtering so a single recipient or time window can be isolated"]},{h:"Usage follows the same record",p:["Usage is derived from the same log rather than counted twice, so a number in a usage view and a number in a filtered log cannot disagree. Segment counts matter here: a long message is several segments and is billed as such, which is why the segmentation guide is worth reading before estimating cost."]},{h:"The log holds metadata, not content",p:["The message log stores metadata only — time, destination number, tenant, provider, sender identity, normalized status, provider message ID and raw error code. Message bodies are not persisted, which keeps a log of your customers’ messages from turning into a second copy of their conversations to govern, export and delete."],bullets:["Stored — time, destination, provider, sender identity, status and error code","Not stored — the message body","Retention applied to the metadata through a time-to-live, per your plan"]}],faq:[{q:"How long are logs kept?",a:"Retention is a platform setting rather than a fixed promise on this page. Choose it deliberately, because it is also a data-protection decision."},{q:"Can I export logs?",a:"Logs and filtering are console features, and the help center covers what can be read and filtered rather than what can be exported."},{q:"Does the log contain the text of messages?",a:"No. The message log stores metadata only, so your system stays the one place that holds message content."}],guides:["data-minimisation","pacing"]},{slug:"tenant-isolation",name:"Tenant isolation",h1:"One tenant per account, one set of credentials each",eyebrow:"Feature · Tenancy",metaTitle:"Tenant isolation — connections, keys, records",metaDescription:"Connections, API keys and message records are held per tenant, so one account’s credentials and traffic are never another’s.",lede:"Isolation is the feature that nobody asks about until it is missing. Holding connections, keys and records per tenant means a shared platform does not become a shared inbox.",sections:[{h:"What is scoped to a tenant",bullets:["Provider connections and their credentials","API keys used to send","Message logs, receipts and usage","Suppression and pacing configuration"]},{h:"Why it matters beyond tidiness",p:["A tenant boundary is also a blast radius boundary: a compromised key sends from one tenant’s accounts rather than everyone’s, and usage reported for one account is measured from that account’s own traffic."]},{h:"What it means in practice",p:["Isolation is a structural boundary in how credentials and records are held. It sits alongside your own access control rather than replacing it, and the obligations that follow from your data stay on your side."]}],faq:[{q:"Can two teams share one tenant?",a:"A tenant is the unit that holds connections and keys. Whether two teams share one or have separate tenants is a decision about your own access model."},{q:"Are message logs visible across tenants?",a:"Records are held per tenant; a tenant sees its own sends, not another’s."},{q:"Where is the data hosted?",a:"If a specific region or residency requirement matters to you, tell us before you plan around it — we will give you the current picture for your deployment."}],guides:["byol","data-minimisation"]},{slug:"console-manual-send",name:"Manual sending from the console",h1:"Send and check messages from the console",eyebrow:"Feature · Console",metaTitle:"Console manual send and message lookup",metaDescription:"The console is where you send a message by hand, look up what happened to one, and read the logs behind a support question.",lede:"Not every message comes from an API. Testing a new sender, resending after a fix, or simply looking up what a customer received — those are console jobs, and they should not require writing code.",sections:[{h:"What the console is for",bullets:["Sending a message by hand, for a test or a one-off","Looking up a single message and reading its status and receipt","Filtering the logs behind a support question","Managing connections, keys and suppression"]},{h:"Where the console fits",p:["Messages your application generates belong in your application, where they are reviewed, versioned and reproducible. The console is for the work that has no home in code: verifying a new sender, resending after a fix, reading the record when a customer asks what they received."]},{h:"Same rules apply",p:["A message sent by hand goes out under the same channel, connection, pacing and suppression rules as one sent by API. There is no bypass, which is deliberate — a test send tells you what production will do."]}],faq:[{q:"Do I need to log in to send?",a:"The console is behind authentication, and the send path itself sits under the same tenant as your API traffic."},{q:"Can I use the console to send to a whole list?",a:"Bulk and scheduled sending exist as console features; their behavior is documented in the help center rather than summarized here."},{q:"Where do I start?",a:"The getting-started article walks from creating a connection to sending the first message, and the API keys article covers using the same tenant from code."}],guides:["message-type-and-consent","byol"]}]},5191:function(e,t,a){a.d(t,{B:function(){return n}});const n=[{slug:"ecommerce-and-retail",name:"E-commerce & retail",h1:"Messaging for e-commerce and retail",eyebrow:"Industry · Retail",metaTitle:"Messaging for e-commerce and retail",metaDescription:"Order confirmations, shipping updates, delivery windows and cart recovery — over the SMS, email and WhatsApp accounts your store already pays for.",lede:"A storefront runs on the messages customers actually read: the confirmation, the dispatch note, the delivery window, the code after a failed payment. Send all of them over the SMS, email and WhatsApp accounts your store already pays for.",sections:[{h:"The messages your store sends every day",p:["Retail traffic divides cleanly into transactional and promotional, and the two have different rules, different send times and very different consequences when they go wrong. The platform treats them as separate message types so the rules never bleed into each other."],bullets:["Order confirmation — immediate, must never be throttled away","Dispatch and shipping updates — tied to a fulfillment event","Delivery windows and out-for-delivery notices","Payment failure and retry reminders","Back-in-stock and restock alerts","Promotional drops — the only category that should carry suppression rules"]},{h:"What the platform takes off your plate",p:["Your store keeps its provider accounts; the platform connects to them and takes over the parts a single account cannot do well. Routing and automatic failover, pacing to the real quota your provider grants each number, segment accounting are implemented on the SMS channel, while normalized delivery receipts and opt-out suppression apply across the channels you connect."],bullets:["Route SMS across more than one provider account, with failover when one stops accepting traffic","Pace sends to the limit the provider actually applies, per sender number","Normalize delivery receipts from each provider into one status a webhook can read","Apply opt-out suppression to promotional traffic only"]},{h:"What stays on your side",p:["Consent capture, the wording of your messages, the links and codes inside them, and the records you keep for each customer remain the store’s responsibility. The platform does not decide who may be messaged, and it does not file or guarantee any registration on your behalf."]}],faq:[{q:"Can the same message go out over email and SMS?",a:"The platform connects to the provider accounts you already hold on each channel, so the same event can be carried on whichever channels you have connected. The channels are configured separately, and the delivery guarantees are not identical between them — automatic failover and per-number pacing are SMS-only, while receipts are normalized wherever the provider reports them back."},{q:"Do you take a cut of what I spend with my provider?",a:"No. You keep your own provider contract and pay them directly. The platform is a layer above those accounts, not a reseller of message credits."},{q:"What happens to a confirmation if my provider goes down?",a:"On the SMS channel, traffic can be routed to another connected account instead of failing outright. That changes which provider carries the message; it does not guarantee that the destination carrier will accept it."}],guides:["message-type-and-consent","delivery-receipts"]},{slug:"fintech-and-payments",name:"Fintech & payments",h1:"Messaging for fintech and payments",eyebrow:"Industry · Fintech",metaTitle:"Messaging for fintech and payments",metaDescription:"One-time codes, transaction alerts and payment reminders over the messaging accounts you already own, with routing and pacing on SMS and receipts normalized wherever the provider reports them.",lede:"In payments the message is often the product: a code that has to land before the session expires, an alert that proves a transaction happened, a reminder that keeps a subscription alive. Connect your own accounts, and the send path stops being the part you have to watch.",sections:[{h:"The messages you cannot afford to lose",bullets:["One-time passwords and step-up verification codes","Transaction and balance alerts","Payment-due and dunning reminders","KYC and document-request follow-ups","Subscription renewal and card-expiry notices"],p:["These messages have hard deadlines. A code that arrives late is a failed login; a reminder that arrives twice looks like fraud. The platform therefore exposes pacing and per-number rate limits explicitly rather than hiding them behind a single auto-scaling counter."]},{h:"Throughput follows your numbers, not a hidden quota",p:["Provider limits apply per sender number and per account, and a single application quota hides the constraint that actually blocks you. The console shows the limit that applies to each connected number, and pacing is applied at that granularity — so adding a second number genuinely doubles throughput instead of splitting the same allowance."]},{h:"Regulatory duty stays with you",p:["Regulatory obligations in financial services — record retention, disclosure wording, sector-specific rules — belong to you and to the provider carrying the traffic; they follow the duty, and the duty sits with you. On the SMS channel the platform’s part is the send path: routing, pacing, and a log that records what went out and what happened to it."]}],faq:[{q:"Can a duplicate code be prevented?",a:"Not by the platform. There is no idempotency key on the send API, so a retried request sends a second message. Duplicate prevention belongs in the caller — the guide on idempotency explains why and what to do instead."},{q:"Are codes delivered on the fastest channel?",a:"You choose the channel by which provider account you send through. The platform does not silently switch channel for you; on SMS it can switch between your connected provider accounts when one stops accepting traffic."},{q:"Does the platform store the content of the messages we send?",a:"No. The message log retains metadata only — time, destination, provider, sender identity, status and error code. Message bodies are not persisted, so content does not accumulate in a log you would later have to govern."}],guides:["data-minimisation","no-idempotency"]},{slug:"healthcare-and-clinics",name:"Healthcare & clinics",h1:"Messaging for healthcare and clinics",eyebrow:"Industry · Healthcare",metaTitle:"Messaging for healthcare and clinics",metaDescription:"Appointment reminders, schedule changes and administrative notices over your own messaging accounts, with the send path and logs kept under your control.",lede:"Most clinic messaging is administrative, and a missed administrative message costs a wasted appointment slot. Send a confirmation at booking and a timed reminder before, on the number the patient gave you — and keep clinical detail out of it.",sections:[{h:"The messages that cut no-shows",bullets:["Appointment confirmations at booking time","Reminders at a fixed interval before the appointment","Rescheduling and cancellation notices","Pre-visit instructions and arrival information","Administrative balance or paperwork reminders"],p:["The pattern that works is a confirmation plus a timed reminder, on the same number the patient booked with, with a one-tap way to change the appointment. Everything else is noise that trains people to ignore the channel."]},{h:"Keep clinical detail out of the message",p:["The platform stores no message bodies — the log keeps metadata only, which removes one place detail could accumulate. What the message says is still yours to decide: content passes through your provider and lands on a handset that may be shared. The practical rule is to send a reference the patient resolves in your own portal rather than the clinical detail itself."]},{h:"Consent and records stay on your side",p:["Who may be contacted, what may be said, and how long records are kept are clinical and professional obligations, and they stay where the duty sits — with the healthcare provider. The platform’s part is getting the message there reliably and keeping a record of the send."]}],faq:[{q:"Do you sign a BAA or equivalent?",a:"Nothing on this site makes that claim. Any agreement of that kind is a contractual matter between you and Whaleal, not a feature of the platform."},{q:"Can patients reply to a reminder?",a:"Replies on the SMS channel can be captured as inbound messages for opt-out handling, but the platform is not an interactive appointment system. The practical pattern is to include a link back to your own booking page."},{q:"Can reminders be sent on more than one channel?",a:"You can connect the accounts you already hold on each channel. Opt-out suppression applies to marketing sends on every channel, and delivery receipts are normalized wherever the provider reports them back — every SMS provider, Resend on email and Meta on WhatsApp."}],guides:["message-type-and-consent","data-minimisation"]},{slug:"logistics-and-delivery",name:"Logistics & delivery",h1:"Messaging for logistics and delivery",eyebrow:"Industry · Logistics",metaTitle:"Messaging for logistics and delivery",metaDescription:"Dispatch notices, arrival windows, failed-delivery rescheduling and proof-of-delivery over the provider accounts you already own.",lede:"A delivery operation lives on contact attempts: the customer who is not home, the gate code nobody has, the parcel heading back to the depot. Each of those is a message that either saves a second trip or causes one.",sections:[{h:"The messages that save a second attempt",bullets:["Dispatch confirmation with a tracking reference","Day-of delivery window, updated when the route changes","Driver-arriving notice ahead of the stop","Failed-delivery notice with a one-tap reschedule link","Depot-collection reminder before a parcel is returned"]},{h:"Batches that drain, and receipts you can read",p:["Delivery messaging is bursty: a route is planned, a batch goes out, then nothing. On the SMS channel the platform spreads the batch to the pacing your provider allows per number, routes around an account that stops accepting traffic, so a batch does not stall partway through. Receipts come back normalized, which is what tells a failed delivery apart from a message that never arrived."],bullets:["Batches spread across connected accounts instead of hammering one","Automatic failover between connected SMS accounts","Receipt status normalized across providers into one webhook payload"]},{h:"It fits next to the systems you already run",p:["Routing, parcel data and your transport management system stay where they are. The platform sends the message you ask it to send, on the account you connected, and reports what happened to it — which makes it a clean fit next to the systems that already know the route."]}],faq:[{q:"Can I send a batch of delivery notices without hitting a rate limit?",a:"The platform paces SMS to the limit your provider applies per sender number, and you can add further numbers or accounts to raise the ceiling. It does not override your provider’s limit for you."},{q:"How do I know a notice was actually delivered?",a:"Providers return delivery receipts, and the platform normalizes them into a single status. Note that a receipt reflects acceptance by the destination network, not that a human read the message."},{q:"Can the same notice go out on WhatsApp as well?",a:"You can connect the accounts you already hold on each channel and send on whichever you choose. Routing and automatic failover between accounts are implemented on the SMS channel today."}],guides:["delivery-receipts","routing-failover"]},{slug:"saas-and-online-services",name:"SaaS & online services",h1:"Messaging for SaaS and online services",eyebrow:"Industry · SaaS",metaTitle:"Messaging for SaaS and online services",metaDescription:"Two-factor codes, onboarding nudges, incident alerts and renewal reminders over the messaging accounts your team already runs.",lede:"Your login codes, incident notices and renewal nudges sit on the critical path of someone else’s workday. Send them from your own service with a tenant API key, and read the outcome back through the same API.",sections:[{h:"The messages on your users’ critical path",bullets:["Two-factor and verification codes","Security alerts — new device, password change","Incident and maintenance notices to affected accounts","Trial expiry and onboarding nudges","Renewal and seat-change reminders"]},{h:"Send from your code, not a console",p:["Product messaging is generated by your application, not typed by a human. The platform exposes an open API for sending, with per-tenant API keys, so the code that emits the event is the code that sends the message. The console is there for operational sends and for looking at what happened."],bullets:["Send from your own service with a tenant API key","Read message status back through the API — acceptance, and the delivery status wherever the provider reports it","Push receipt events to your own endpoint instead of polling"]},{h:"Your notification policy stays yours",p:["Which of your users may be messaged, how often, and what a message is allowed to say — that is your product decision. On the SMS channel the platform applies the routing, pacing and suppression rules you configure; it does not decide your notification policy."]}],faq:[{q:"Can I send the same code from two services without duplicating it?",a:"Not automatically. The send API has no idempotency key, so a retried call produces a second message. Duplicate suppression has to live in the caller."},{q:"Do you retry a failed send for me?",a:"Retry behavior is explicit rather than automatic: a failed message records its error code, and re-sending is a decision your service makes. Scheduling and bulk behavior are documented in the help center."},{q:"Can receipts be pushed to our own webhook?",a:"Yes — the platform can push delivery receipt events to an endpoint you configure. The reliability caveats for callbacks are covered in the guides."}],guides:["no-idempotency","callback-reliability"]},{slug:"education-and-training",name:"Education & training",h1:"Messaging for education and training",eyebrow:"Industry · Education",metaTitle:"Messaging for education and training",metaDescription:"Enrollment confirmations, schedule changes, deadline reminders and attendance notices over the messaging accounts your institution already holds.",lede:"Education messaging is about timing: a class that moved, a deadline that is close, an enrollment nobody confirmed. The failure mode is not a missing message — it is one that arrives after it mattered.",sections:[{h:"What your institution sends each term",bullets:["Enrollment and registration confirmations","Schedule changes and room moves","Assignment and payment deadline reminders","Attendance and absence notices","Event and term-start reminders to a cohort"]},{h:"Send to a whole cohort without tripping a limit",p:["Sending to a whole cohort at once is a burst, and providers apply a limit per sender number. The platform spreads a batch to that limit rather than failing partway through, and the pacing is visible in the console so a term-start send does not quietly become a two-hour job."],bullets:["Batch and scheduled sends spread to the provider limit per number","Bulk and scheduled behavior documented in the help center","Opt-out suppression applied to promotional sends, not to transactional ones"]},{h:"Who may be contacted is your call",p:["Guardian consent, age-related rules and institutional policy decide who can be messaged. The platform applies the rules you configure — it carries out that judgment rather than making it for you."]}],faq:[{q:"Can one campaign go out to several thousand people at once?",a:"You can submit a batch, and the platform paces it to what your provider allows per number. Throughput rises with the number of connected sender numbers or accounts, not by overriding the provider limit."},{q:"Can a scheduled send be canceled?",a:"Scheduled and bulk sending is a console feature; the exact behavior is documented in the help center rather than assumed here."},{q:"Do you support more than one language in a message?",a:"Content is whatever you put in the request, so any language your provider supports can be sent. Note that non-Latin scripts change how a message is split into segments, which affects cost."}],guides:["message-type-and-consent","pacing"]},{slug:"marketplaces-and-platforms",name:"Marketplaces & platforms",h1:"Messaging for marketplaces and platforms",eyebrow:"Industry · Marketplaces",metaTitle:"Messaging for marketplaces and platforms",metaDescription:"Buyer and seller notifications, order and dispute updates over the provider accounts your platform already holds.",lede:"A marketplace messages two audiences about the same event for opposite reasons: the buyer wants it to arrive, the seller wants proof that it did. That makes the receipt the part worth getting right.",sections:[{h:"Two audiences, one event",bullets:["Order placed, confirmed and shipped — to both sides","Dispute, refund and chargeback status changes","Payout and settlement notices to sellers","Review and rating prompts after completion","Account and verification notices"]},{h:"The receipt is the audit trail",p:["When a seller disputes whether they were told something, the answer has to be a record rather than a recollection. The platform logs each send, normalizes provider delivery receipts into one status and can push those events to your own endpoint — so the record lives in your system too."]},{h:"Where your platform ends and ours starts",p:["Your platform decides who is notified and what the notification says. On the SMS channel the messaging layer decides how it leaves the building — which connected account carries it, at what pace, and what receipt comes back."]}],faq:[{q:"Can we tell whether a specific seller was notified?",a:"Sends and their statuses are logged, and receipts can be pushed to an endpoint you control. Note that a receipt means the destination network accepted the message, not that it was read."},{q:"Is there a callback retry policy?",a:"Callback delivery is deliberately not treated as fire-and-forget; the reliability model and its limits are set out in the callback guide."},{q:"Can different sellers use their own provider accounts?",a:"Connections are held per tenant. Whether each seller is a separate tenant, and therefore has their own connections and API keys, is a design decision on your side."}],guides:["callback-reliability","no-idempotency"]},{slug:"travel-and-hospitality",name:"Travel & hospitality",h1:"Messaging for travel and hospitality",eyebrow:"Industry · Travel",metaTitle:"Messaging for travel and hospitality",metaDescription:"Booking confirmations, check-in links, arrival information and disruption alerts over the messaging accounts you already own.",lede:"Travel messaging is shaped by the clock: a confirmation that has to arrive immediately, a reminder the evening before, a disruption notice that is worthless once the guest has left for the airport. Send each one from an account that is still accepting traffic.",sections:[{h:"From booking to arrival",bullets:["Booking confirmation with a reference","Pre-arrival check-in and directions","Day-of arrival time and access information","Disruption, delay and cancellation alerts","Post-stay review requests"]},{h:"The one day you cannot afford a second failure",p:["A disruption notice goes out when something has already gone wrong, which is the worst moment to discover that one provider account has stopped accepting traffic. On the SMS channel the platform can route to another connected account instead of failing, and normalized receipts show what actually left."],bullets:["Automatic failover between your connected SMS accounts","Delivery receipts normalized into one status","Per-number pacing so a wide disruption send does not stall"]},{h:"Guest consent stays with you",p:["Guest consent, the accuracy of the information you send and any local rules about contacting travelers are your responsibility. The platform carries the message, not the decision to send it."]}],faq:[{q:"Can a message go out in the guest’s own language?",a:"Content is whatever you send, so any language the channel supports is possible. Non-Latin scripts change message segmentation, which affects message count and therefore cost."},{q:"What if a guest replies to a disruption notice?",a:"Replies are captured as inbound messages and can be surfaced, but the platform is not a guest-services inbox. Route replies to your own system if you need to act on them."},{q:"Can we send on WhatsApp as well as SMS?",a:"You can connect the accounts you hold on each channel and choose which one carries a given message. Routing and automatic failover are implemented for SMS; opt-out suppression applies to marketing sends on every channel, and receipts are normalized wherever the provider reports them."}],guides:["delivery-receipts","routing-failover"]},{slug:"on-demand-and-field-services",name:"On-demand & field services",h1:"Messaging for on-demand and field services",eyebrow:"Industry · Field services",metaTitle:"Messaging for on-demand and field services",metaDescription:"Job dispatch, arrival windows and technician ETA messages over the messaging accounts your operation already holds.",lede:"Field service messaging is measured in minutes: a technician twenty minutes away, a job that moved, a customer who will not be in. Send the ETA when the event happens and it saves a trip; send it late and it is worse than silence.",sections:[{h:"The messages that protect the day’s schedule",bullets:["Job accepted and scheduled confirmation","Day-of arrival window","Technician en-route notice with an ETA","Delay or reschedule notice","Completion and follow-up request"]},{h:"Send-time is the constraint, not volume",p:["An ETA message that arrives late is worse than no message. Because provider limits apply per sender number, a wide dispatch at the same minute can queue behind itself — which is exactly why pacing is configured per number and visible in the console rather than hidden behind one shared allowance."],bullets:["Per-number pacing so a dispatch burst drains predictably","Sender selection so operational traffic uses the right number","Automatic failover between connected SMS accounts"]},{h:"It fits alongside your dispatch system",p:["Dispatch stays with your dispatch system, which knows the technician’s route and the customer’s address. The platform sends the message it is told to send and reports whether it left — so the two systems keep the jobs they are good at."]}],faq:[{q:"Can we send from a different number for each region?",a:"You connect the numbers you own and choose which one a send uses, so a per-region number is a configuration rather than a code change."},{q:"Will the platform hold messages and send them later?",a:"Scheduled and bulk sending exist as console features. They do not turn the platform into a task queue for time-critical traffic; for ETAs, send when the event happens."},{q:"How do we know a dispatch notice went out?",a:"Each send is logged with its status, and delivery receipts can be pushed to your own endpoint. A receipt confirms the destination network accepted the message, not that the customer read it."}],guides:["pacing","sender-selection"]}]},7338:function(e,t,a){a.d(t,{F:function(){return n}});const n=[{slug:"byol-vs-reselling",name:"Bringing your own provider vs buying credits",h1:"Bring your own provider accounts vs buying message credits from a platform",eyebrow:"Compare · Commercial model",metaTitle:"BYOL vs buying credits — keep your own rates",metaDescription:"Why the platform connects to accounts you already hold instead of selling credits: your rate stays yours and switching stays a configuration change.",lede:"We connect to the provider accounts you already pay for, and we never sell you message credits. That one decision sets your rate, your switching cost, and who owns the relationship — everything below follows from it.",sections:[{h:"Why we connect instead of reselling",bullets:["Your rate is your rate — nothing is added on top of the price you already negotiated, because there is no balance in the middle to mark up","Your commitment stays with your provider, so a change of tools never strands volume you already bought","You remain the customer of record — for pricing, for registrations, for sender identity","Disconnecting leaves your account untouched: leaving is a configuration change, not a migration"]},{h:"What a credit balance changes",p:["A prepaid balance is genuinely simpler to budget — one invoice, one number to watch. What it moves out of view is the rate underneath: you know what you paid, not what the message cost. That is also why leaving a balance-holder means migrating accounts rather than changing a setting."],bullets:["Your provider invoice, at your rate — versus one blended balance","Volume commitments you control — versus a balance somebody else holds","Switching tools by changing configuration — versus moving accounts"]},{h:"How to get the most out of this model",p:["Bring the account you already have and keep the registrations in your own name. The layer adds routing, pacing, receipts and logs on top; everything commercial stays exactly where it was, so there is nothing to unwind if you ever stop."]}],faq:[{q:"Does Whaleal take a margin on messages?",a:"No. There is no credit balance to mark up — you pay your provider directly, and the platform never sits in the middle of the money."},{q:"Can I start with a single provider?",a:"Yes. Connecting one account is a fully supported setup, and it is where most teams start. Routing and failover are there for the day you add a second."},{q:"What happens to our provider contract if we adopt the platform?",a:"It stays yours, on your terms and your rates. The platform is given credentials to send through the account and read status back — nothing more, and nothing that touches the contract."}],guides:["byol"]},{slug:"orchestration-vs-bsp",name:"Orchestration layer vs becoming your own BSP",h1:"Using an orchestration layer vs becoming your own BSP",eyebrow:"Compare · Architecture",metaTitle:"Orchestration layer vs becoming your own BSP",metaDescription:"Why the platform sits above the provider APIs rather than holding carrier relationships: your rates, registrations and sender identity stay yours.",lede:"We chose to sit above the provider APIs rather than hold carrier relationships — because that is the arrangement that keeps your rates, your registrations and your sender identity in your own name. Here is what that choice puts in your hands.",sections:[{h:"What we do, and what that keeps yours",bullets:["We add routing, failover and pacing on the SMS channel, plus normalized receipts, suppression and a send log above the accounts you already hold","Carrier relationships and registrations stay with your provider, filed in your name","Nothing in the middle can reprice your traffic or lift a carrier filter","Your volume commitments and your sender identities are never held by us"]},{h:"What holding carrier relationships actually requires",p:["Holding carrier relationships is a permanent engineering and regulatory commitment — registrations, sender verification, country rules, and commercial liability for delivery. Those obligations exist in both models; becoming a BSP adds the sending platform on top of them rather than replacing them."],bullets:["Standing up senders is the easy part of either route","The hard part is the permanent obligations, which do not disappear when you self-host","Receipt normalization is ongoing work, because each provider reports in its own vocabulary and changes it"]},{h:"Built for teams whose product is something else",p:["The layer is built for teams whose product is something else: it keeps messaging dependable without letting it become the business. If messaging is itself what you sell, owning the carrier relationship may well be the point, and the layer still sits above it — the two arrangements are not exclusive, and choosing this one does not stop you from holding relationships of your own."]}],faq:[{q:"Does Whaleal hold a carrier relationship?",a:"No, and that is deliberate. Staying above your provider is what keeps your rates, your registrations and your sender identity in your own name rather than in ours."},{q:"Will the platform file registrations for me?",a:"Registration and sender verification are filed by you, in your own name — which is exactly why they stay with you whichever way you send."},{q:"Is self-hosting cheaper?",a:"It depends what you count. What the layer takes off your plate is the permanent part: the engineering attention a sending platform needs after the first message works — pacing, failover, receipt normalization and suppression as providers change."}],guides:["byol","delivery-receipts"]},{slug:"multi-provider-vs-single-provider",name:"Several connected accounts vs one",h1:"Several connected SMS accounts vs a single provider account",eyebrow:"Compare · Resilience",metaTitle:"Multiple provider accounts vs a single account",metaDescription:"What a second connected account buys you: failover when one stops accepting traffic, throughput that actually grows, and coverage a single account cannot hold.",lede:"A single account is a single point of failure you cannot see breaking until customers tell you. Connecting a second turns that into failover you configure once — which is why routing belongs in the layer rather than bolted on later.",sections:[{h:"What a second connected account gives you",bullets:["Automatic failover when one account stops accepting traffic — the message moves instead of failing","Throughput that genuinely grows, because pacing is applied per sender number and each account brings its own","Coverage across destinations where a single account cannot hold every identity","One routing decision, configured once, instead of a single default path you hope holds"]},{h:"What it takes to hold two accounts well",bullets:["Two registrations to keep current — the console keeps them visible rather than hiding them behind one number","Receipts and logs matter more with two accounts, which is why normalization is part of the layer rather than an add-on","Failover only helps when accounts fail independently — two numbers on the same provider is not resilience"]},{h:"How to sequence it",p:["Start with one account and take it end to end. Add the second when a specific ceiling — a per-number limit, an outage, a destination you cannot reach — is the thing standing in your way. The layer is built so that connecting the second account is the whole change."]}],faq:[{q:"Is failover available on every channel?",a:"Automatic failover between connected accounts ships on the SMS channel today — the channel where a provider-side outage is the failure that costs you messages. Email and WhatsApp carry their own provider-side limits and are handled by those channels."},{q:"Does more accounts mean less pacing discipline?",a:"No — that is the point. Pacing still applies per sender number, so more numbers raise the ceiling rather than removing the limit."},{q:"Do we need two accounts to use the platform?",a:"No. One account is a fully supported setup; the second is there for the day you want failover rather than a single path."}],guides:["routing-failover","two-rate-limits"]},{slug:"build-vs-buy-the-layer",name:"Building the layer yourself vs using one",h1:"Building the sending layer yourself vs using one",eyebrow:"Compare · Build or buy",metaTitle:"Build vs buy for dependable messaging",metaDescription:"The work between “we can call an API” and “messaging is dependable”: pacing and failover on the SMS channel, normalized receipts, suppression and logs — kept off your roadmap.",lede:"Calling a provider API takes an afternoon. Making messaging dependable is a list of unglamorous problems that only show up in production — and that list is what we maintain so your team does not have to.",sections:[{h:"The list we keep off your roadmap",bullets:["Per-number pacing, at the limit your provider actually applies to the number","Failover across accounts, plus telling an outage from a bad route (SMS channel)","Receipt normalization, so you read one status instead of every provider’s vocabulary","Suppression that catches opt-outs exactly, and does not catch them by accident","Logs that answer a support question while holding metadata rather than message bodies","A record of what was sent, per recipient, provable after the fact"]},{h:"Why this is worth buying rather than building",p:["None of it is hard in isolation. Each item is discovered from an incident, fixed under pressure, and then maintained as providers change their behavior. Buying the layer is how that maintenance stops being your team’s problem — and how nobody gets paged at 3am for a provider’s rate-limit change."]},{h:"Keep the parts that are yours",p:["Your application still owns the decision to send, the content, and the record that matters to your business. You can route some traffic through the layer and leave the rest direct — the accounts stay yours, so the choice is reversible at any point."]}],faq:[{q:"Can we use the platform for some traffic and direct for the rest?",a:"Yes. The platform connects to accounts you already have, so a subset of traffic can route through it while the rest continues unchanged."},{q:"Is there an open API?",a:"Yes — sends go over HTTP with per-tenant keys, and the SMS channel is the published reference today. The API reference lists each endpoint with its request shape."},{q:"What does the platform take off my team’s plate?",a:"A specific list of responsibilities — pacing and failover on the SMS channel, receipt normalization, suppression and logs — maintained as providers change their behavior. Everything else, including your own product, stays with your team."}],guides:["pacing","no-idempotency"]},{slug:"direct-provider-vs-orchestration",name:"Sending straight from a provider vs through a layer",h1:"Sending straight from your provider vs through an orchestration layer",eyebrow:"Compare · Approach",metaTitle:"Direct provider sending vs an orchestration layer",metaDescription:"What the layer adds once more than one team or account has to send coherently: one integration, cross-provider routing, one normalized status.",lede:"Sending direct is the fastest way to send the first message. The layer is what keeps messaging dependable once a second provider, a second team or a second failure arrives — and it adds nothing you have to migrate away from.",sections:[{h:"What the layer adds on top of direct sending",bullets:["One integration across providers instead of one per provider, with one place every team sends from","Cross-provider routing, failover and pacing handled at the layer rather than rebuilt by each team (SMS channel)","One normalized status, so a receipt means the same thing whichever account carried the message","Suppression held in one place and applied consistently, wherever a send originates"]},{h:"How the layer fits alongside direct sending",p:["The layer does not replace direct sending — it sits above it. Your provider keeps its own features and you keep one relationship; what the layer adds is the cross-provider behavior a single direct integration cannot give you, and adopting it later is a matter of connecting accounts rather than renegotiating anything."]},{h:"How the two fit together",p:["Start direct, and add the layer when more than one team or more than one account has to send coherently. Because the accounts stay yours, the layer is a configuration you add and can remove — not a migration you commit to on day one."]}],faq:[{q:"Do we lose provider features by going through a layer?",a:"The layer carries the capabilities it implements for each connection, and the integrations pages list them per provider — so the answer is checkable rather than assumed. Anything the layer does not carry, your provider account still does, directly."},{q:"Can we start direct and move later?",a:"Yes, and that is often the right order. Because the accounts stay yours, adopting the layer later means connecting them rather than renegotiating anything."},{q:"What happens to our provider-specific setup?",a:"It stays exactly where it is. The layer sends through the account you already configured and reads status back from it, so nothing about your provider setup has to change to try it."}],guides:["byol","callback-reliability"]}]}}]);
//# sourceMappingURL=f114e5957a7d5100e19d0d07df690bdf4b945c70-7929496c0e843e275833.js.map